import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v > 0);
        vm.assume(address(this).balance >= v);
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: v}() {} catch { return; }
        assertTrue(c.balances(address(this)) == b0 + v);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    fallback() external payable {}

    receive() external payable {}
}
